// This file is generated by AI.

// 场景浏览器的自绘对话框: 名称输入 (新建场景/新建文件夹/重命名) 与删除确认。
// 与设置/未保存对话框一致使用自绘模态层, 避免 WebView 中弹层定位/动画异常。

import { Button, Input } from '@fluentui/react-components';
import { useEffect, useRef, useState } from 'react';

interface BaseDialogProps {
  onClose: () => void;
}

/** 名称输入对话框。
 *
 * `onSubmit` 返回错误信息时保持打开并展示; 返回 null 表示成功 (自动关闭)。
 * `validate` 用于提交前的格式/重名校验 (可异步)。
 */
export interface NameInputDialogProps extends BaseDialogProps {
  title: string;
  label: string;
  initialValue?: string;
  placeholder?: string;
  hint?: string;
  /** 聚焦时仅选中主文件名 (保留扩展名), 用于重命名场景文件 */
  selectStem?: boolean;
  submitLabel?: string;
  validate?: (name: string) => Promise<string | null>;
  onSubmit: (name: string) => Promise<string | null>;
}

export function NameInputDialog({
  title,
  label,
  initialValue = '',
  placeholder,
  hint,
  selectStem = false,
  submitLabel = '确定',
  validate,
  onSubmit,
  onClose,
}: NameInputDialogProps) {
  const [value, setValue] = useState(initialValue);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const input = inputRef.current;
    if (!input) return;
    input.focus();
    if (selectStem) {
      const dot = value.lastIndexOf('.');
      if (dot > 0) input.setSelectionRange(0, dot);
      else input.select();
    } else {
      input.select();
    }
  }, []);

  const submit = async () => {
    if (busy) return;
    const name = value.trim();
    if (!name) {
      setError('名称不能为空');
      return;
    }
    if (validate) {
      const err = await validate(name);
      if (err) {
        setError(err);
        return;
      }
    }
    setBusy(true);
    const err = await onSubmit(name);
    setBusy(false);
    if (err) setError(err);
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal-surface small-surface" onClick={(e) => e.stopPropagation()}>
        <h2 className="modal-title">{title}</h2>
        <div className="prompt-field">
          <span className="settings-label">{label}</span>
          <Input
            ref={inputRef}
            value={value}
            placeholder={placeholder}
            onChange={(_, data) => {
              setValue(data.value);
              setError(null);
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter') void submit();
              if (e.key === 'Escape') onClose();
            }}
            disabled={busy}
          />
          {hint ? <span className="prompt-hint">{hint}</span> : null}
          {error ? <span className="prompt-error">{error}</span> : null}
        </div>
        <div className="modal-actions">
          <Button appearance="primary" disabled={busy} onClick={() => void submit()}>
            {submitLabel}
          </Button>
          <Button appearance="secondary" disabled={busy} onClick={onClose}>
            取消
          </Button>
        </div>
      </div>
    </div>
  );
}

/** 删除确认对话框。`onConfirm` 返回错误信息时保持打开; 返回 null 表示成功 (自动关闭)。 */
export interface ConfirmDialogProps extends BaseDialogProps {
  title: string;
  message: string;
  confirmLabel?: string;
  danger?: boolean;
  onConfirm: () => Promise<string | null>;
}

export function ConfirmDialog({
  title,
  message,
  confirmLabel = '确定',
  danger = false,
  onConfirm,
  onClose,
}: ConfirmDialogProps) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const confirm = async () => {
    if (busy) return;
    setBusy(true);
    const err = await onConfirm();
    setBusy(false);
    if (err) setError(err);
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal-surface small-surface" onClick={(e) => e.stopPropagation()}>
        <h2 className="modal-title">{title}</h2>
        <p className="confirm-message">{message}</p>
        {error ? <p className="prompt-error">{error}</p> : null}
        <div className="modal-actions">
          <Button
            appearance="primary"
            className={danger ? 'danger-button' : undefined}
            disabled={busy}
            onClick={() => void confirm()}
          >
            {confirmLabel}
          </Button>
          <Button appearance="secondary" disabled={busy} onClick={onClose}>
            取消
          </Button>
        </div>
      </div>
    </div>
  );
}
